<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ziyaret detayı - AdGuard</title><link rel="stylesheet" href="/assets/app.css"></head>
<body><main class="container"><h1>Ziyaret detayı</h1><p><a href="/visits">Ziyaretlere dön</a></p><dl><dt>Site</dt><dd><?= e($visit['website_name']) ?></dd><dt>Tarih</dt><dd><?= e($visit['created_at']) ?></dd><dt>IP</dt><dd><?= e($visit['ip_text']) ?></dd><dt>User-Agent</dt><dd><?= e($visit['user_agent']) ?></dd><dt>Sayfa</dt><dd><?= e($visit['page_url']) ?></dd><dt>Referrer</dt><dd><?= e($visit['referrer']) ?></dd><dt>Risk</dt><dd><?= e($visit['risk_level']) ?> (<?= (int)$visit['risk_score'] ?>/100)</dd></dl><h2>Tespit sinyalleri</h2><?php if(!$reasons): ?><p>Ek risk sinyali bulunamadı.</p><?php else: ?><ul><?php foreach($reasons as $reason): ?><li><?= e($reason['description']??$reason['code']??'Sinyal') ?> (<?= (int)($reason['weight']??0) ?>)</li><?php endforeach; ?></ul><?php endif; ?></main></body></html>
